message.content:
{
  "description": "The creature is shown in left-facing profile as a quadrupedal animal with the overall size, proportions, fur, head shape, and paws of a brown bear, but extensively covered with a glossy, hard, dark brown to black exoskeleton resembling a beetle. The bear's brown furry head, four clawed paws, pale segmented underbelly, and short bushy tail remain visible beneath and around the armor. The armor is smooth, shiny, and composed of overlapping domed plates covering the top of the head, the back of the neck, the entire dorsal surface from shoulders to rump, the sides, shoulders, hips, and the outer surfaces of all four legs. Two large curved horns project from the head and neck armor. The animal stands on all four feet on a plain light background.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense medium-brown fur on the cheeks and neck, a lighter tan muzzle, a black nose at the tip, a small dark brown eye, and a slightly open mouth",
      "where": "at the front of the body, facing left, with the neck joining the armored torso"
    },
    {
      "part": "horns",
      "looks_like": "two large, smooth, glossy black horns like a rhinoceros beetle; the front horn is shorter, upright and forked with small points, arising from the forehead plate; the rear horn is much longer, thick at the base and tapering to a sharp tip, curving strongly forward and upward over the head",
      "where": "on top of the head and on the large plate covering the back of the head and upper neck"
    },
    {
      "part": "ears",
      "looks_like": "small, rounded, brown furry ears",
      "where": "on the sides of the head just behind the front horn, partially tucked under the edge of the glossy head plate"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular legs with brown fur visible at the joints and underbelly, each largely sheathed in large, smooth, glossy black plates over the upper and lower segments",
      "where": "two forelegs under the shoulder armor and two hindlegs under the hip armor, supporting the body in a standing quadrupedal posture"
    },
    {
      "part": "feet",
      "looks_like": "broad brown furry paws with five toes and long, curved, dark claws",
      "where": "at the bottom of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, bushy, brown furry tail",
      "where": "protruding from the rear of the body beneath the last dorsal plate, above the hindlegs"
    },
    {
      "part": "shell",
      "looks_like": "a hard, smooth, highly glossy dark brown-black carapace forming a helmet over the head and a continuous dorsal covering",
      "where": "covering the top of the head, the back of the neck, and the entire back from shoulders to rump"
    },
    {
      "part": "plates",
      "looks_like": "numerous overlapping, smooth, domed, glossy black plates with visible segmentation; the dorsal plates are large and transverse across the back, the shoulder and hip plates are large and rounded, the leg plates are shin-like, and the ventral surface is pale beige with transverse segmentation and a lateral row of small oval openings with dark centers",
      "where": "dorsal plates in a row along the back and sides, shoulder plates over the forequarters, hip plates over the hindquarters, shin plates on the front and back of each leg, and pale segmented plates on the throat, chest, belly, and lower sides"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
